import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import type {ConnectionManager} from '../../packages/core/src/connections.js';
import {DatabaseDefinitions} from '../../packages/core/src/database-definitions.js';
import {ddlSegments,ddlQuote} from '../../packages/core/src/ddl-syntax.js';
import {sqlTokens,sqlIdentifier,sqlSources} from '../../packages/core/src/sql-editing.js';
import {structureFingerprint} from '../../packages/core/src/schema-changes.js';
import {readTableStructure} from '../../packages/core/src/table-structure.js';
import type {DefinitionSnapshot,DefinitionPreviewResult} from '../../packages/protocol/src/index.js';
const reviewed=(p:DefinitionPreviewResult)=>{assert.equal(p.kind,'preview');if(p.kind!=='preview')throw new Error('Expected preview');return p.preview;};
export async function tableDefinitionContract(manager:ConnectionManager,id:string){
 const service=new DatabaseDefinitions(manager),base=await manager.connect(id),d=base.profile.driver,mysql=d!=='postgresql',q=(n:string)=>ddlQuote(n,d),schema=mysql?base.profile.database!:'public',qualified=(n:string)=>q(schema)+'.'+q(n),prefix='draft_'+randomUUID().replaceAll('-','').slice(0,9),name=prefix+'_t',child=prefix+'_child',audit=prefix+'_audit',idx=prefix+'_ix',table=qualified(name),trigger=prefix+'_tr',view=prefix+'_view';
 const read=async()=>{const ref=(await service.list(id,schema)).find(r=>r.kind==='table'&&r.name===name)!;assert(ref);const s=await service.read(id,ref);assert(s?.tableStructure);assert(s.editable,s.notes.join('\n'));return s;};
 const renameText=(sql:string,from:string,to:string)=>{let text=sql;for(const token of sqlTokens(sql,d,base.sqlMode).filter(t=>['word','identifier'].includes(t.kind)&&sqlIdentifier(t.text)===from).reverse())text=text.slice(0,token.start)+q(to)+text.slice(token.end);return text;};
 const apply=async(b:DefinitionSnapshot,sql:string,renames:{from:string;to:string}[]=[])=>{const p=reviewed(await service.preview(b,sql,renames));const r=await service.apply(id,p.token);assert.equal(r.status,'succeeded',r.error);assert(r.snapshot?.tableStructure);return r.snapshot;};
 await base.query(`CREATE TABLE ${table}(id ${mysql?'INT PRIMARY KEY AUTO_INCREMENT':'INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY'},label VARCHAR(40) NOT NULL DEFAULT 'old'${mysql?" COMMENT 'retained'":''},amount TEXT,payload ${mysql?'BLOB':'BYTEA'},n BIGINT,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP${mysql?' ON UPDATE CURRENT_TIMESTAMP':''},seed INT NOT NULL DEFAULT 7,g INT GENERATED ALWAYS AS(seed*2) STORED,CONSTRAINT ${q(prefix+'_ck')} CHECK(length(label)>0))`);
 await base.query(`CREATE TABLE ${qualified(child)}(id INT,CONSTRAINT ${q(prefix+'_fk')} FOREIGN KEY(id) REFERENCES ${table}(id))`);await base.query(`CREATE TABLE ${qualified(audit)}(id INT)`);await base.query(`CREATE UNIQUE INDEX ${q(idx)} ON ${table}(label)`);
 if(!mysql){await base.query(`COMMENT ON INDEX ${q(schema)}.${q(idx)} IS 'index comment'`);await base.query(`COMMENT ON CONSTRAINT ${q(prefix+'_ck')} ON ${table} IS 'check comment'`);await base.query(`ALTER TABLE ${table} REPLICA IDENTITY USING INDEX ${q(idx)}`);await base.query(`ALTER TABLE ${table} CLUSTER ON ${q(idx)}`);await base.query(`CREATE FUNCTION ${qualified(prefix+'_fn')}() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO ${qualified(audit)} VALUES(NEW.id); RETURN NEW; END $$`);await base.query(`CREATE TRIGGER ${q(trigger)} AFTER UPDATE ON ${table} FOR EACH ROW EXECUTE FUNCTION ${qualified(prefix+'_fn')}()`);}
 else await base.query(`CREATE TRIGGER ${qualified(trigger)} AFTER UPDATE ON ${table} FOR EACH ROW INSERT INTO ${qualified(audit)} VALUES(NEW.id)`);
 try{
  await base.query(`INSERT INTO ${table}(id,label,amount,payload,n,created_at) VALUES(7,'one','discard',${mysql?"x'00ff'":"decode('00ff','hex')"},9223372036854775807,'2000-01-02 03:04:05')`);await base.query(`INSERT INTO ${qualified(child)} VALUES(7)`);
  let before=await read();const oldOid=mysql?undefined:JSON.parse(before.tableStructure!.identity).oid;assert.equal((await base.details(qualified(child))).foreignKeys.length,1);
  if(mysql)await base.query(`INSERT INTO ${table}(id,label) VALUES(200,'two')`);
  let sql=renameText(before.sql,'label','name');const first=sql.indexOf(';'),create=first<0?sql:sql.slice(0,first),rest=first<0?'':sql.slice(first+1),parsed=ddlSegments(create,d,base.sqlMode);
  const columns=parsed.segments.filter(c=>c.column!==undefined&&c.column!=='amount').map(c=>c.column==='name'?c.text.replace(/(?:character varying|varchar)\(40\)/i,'VARCHAR(80)'):c.column==='g'?c.text.replace(/\b2\b/,'3'):c.text);
  sql=parsed.prefix+'\n'+[...columns,"status VARCHAR(20) NOT NULL DEFAULT 'active'",...parsed.segments.filter(c=>c.column===undefined).map(c=>c.text)].join(',\n')+'\n'+parsed.suffix+';\n'+rest;
  const pattern=mysql?new RegExp('(`'+idx+'`\\s*\\(`name`)(\\))','i'):new RegExp('(INDEX "?'+idx+'"? ON [^;]+?\\(\\s*"name")(\\))','i');
  const editedIndex=sql.replace(pattern,'$1 DESC$2');assert.notEqual(editedIndex,sql,'The fixture must edit the actual server index representation');sql=editedIndex;
  const p=reviewed(await service.preview(before,sql,[{from:'label',to:'name'}]));assert(p.warnings.some(w=>w.includes('amount')));if(mysql)assert(!p.steps.some(sql=>/AUTO_INCREMENT\s*=/.test(sql)));assert.equal((await base.query(`SELECT label FROM ${table} WHERE id=7`)).rows[0]?.c0,'one');
  const r=await service.apply(id,p.token);assert.equal(r.status,'succeeded',r.error);assert(r.snapshot?.tableStructure);before=r.snapshot;
  assert.deepEqual((await base.query(`SELECT id,name,payload,n,g,status,created_at FROM ${table} WHERE id=7`)).rows[0],{c0:7,c1:'one',c2:{type:'binary',base64:'AP8='},c3:{type:'integer',value:'9223372036854775807'},c4:21,c5:'active',c6:'2000-01-02 03:04:05'});
  assert.equal((await base.query(`SELECT id FROM ${qualified(child)}`)).rows[0]?.c0,7);assert.equal((await base.details(qualified(child))).foreignKeys.length,1);await base.query(`UPDATE ${table} SET name='edited' WHERE id=7`);assert.equal((await base.query(`SELECT id FROM ${qualified(audit)}`)).rows[0]?.c0,7);if(mysql){await base.query(`INSERT INTO ${table}(name) VALUES('next')`);assert.equal((await base.query(`SELECT id FROM ${table} WHERE name='next'`)).rows[0]?.c0,201);}
  const actualStructure=before.tableStructure;assert(actualStructure);if(mysql){assert.match(before.rawSql,/retained/);}else{assert.equal(JSON.parse(actualStructure.identity).oid,oldOid);const i=actualStructure.indexes.find(i=>i.name===idx)!;assert.equal(i.comment,'index comment');assert(i.replicaIdentity);assert(i.clustered);assert.equal(actualStructure.constraints.find(c=>c.name===prefix+'_ck')?.comment,'check comment');}
  const noChange=reviewed(await service.preview(before,before.sql));assert.equal(noChange.steps.length,0);assert.equal((await service.apply(id,noChange.token)).completed,0);
  const count=(await base.query(`SELECT count(*) FROM ${table}`)).rows[0]?.c0,stable=structureFingerprint(await readTableStructure(base,table),d),sources=sqlSources(before.sql,d,base.sqlMode),original=ddlSegments(sources[0]!.sql,d,base.sqlMode);
  const bad=original.prefix+original.segments.map(p=>p.tokens[0]?.text.toUpperCase()==='CONSTRAINT'&&sqlIdentifier(p.tokens[1]!.text)===prefix+'_ck'?`CONSTRAINT ${q(prefix+'_ck')} CHECK(id>100000)`:p.text).join(', ')+original.suffix+';\n'+sources.slice(1).map(s=>s.sql).join('\n');assert.notEqual(bad,before.sql);const invalid=reviewed(await service.preview(before,bad));const failed=await service.apply(id,invalid.token);assert.equal(failed.status,'failed');if(!mysql)assert(failed.rolledBack);assert.equal(structureFingerprint(await readTableStructure(base,table),d),stable);assert.equal((await base.query(`SELECT count(*) FROM ${table}`)).rows[0]?.c0,count);
  if(mysql){
   const originalLease=manager.lease.bind(manager);manager.lease=async(id,owner)=>{const s=await originalLease(id,owner);await s.query("SET SESSION sql_mode=''");return s;};
   try{const current=await read(),short=current.sql.replace(/varchar\(80\)/i,'VARCHAR(2)');assert.notEqual(short,current.sql);const p=reviewed(await service.preview(current,short));assert.match(p.steps[0]!,/STRICT_ALL_TABLES/);const report=await service.apply(id,p.token);assert.equal(report.status,'failed');assert.equal((await base.query(`SELECT name FROM ${table} WHERE id=7`)).rows[0]?.c0,'edited');assert.equal(structureFingerprint(await readTableStructure(base,table),d),stable);}finally{manager.lease=originalLease;}
   const current=await read(),late=reviewed(await service.preview(current,current.sql.replace(/DEFAULT 'active'/i,"DEFAULT 'ready'"))),abort=new AbortController();assert(late.steps.some(s=>s.includes("'ready'")));
   manager.lease=async(id,owner)=>{const s=await originalLease(id,owner);if(owner.startsWith('ddl-apply:')){const query=s.query.bind(s);s.query=async(sql,limit)=>{const result=await query(sql,limit);if(/^\s*ALTER\s+TABLE\b/i.test(sql))abort.abort();return result;};}return s;};
   try{const report=await service.apply(id,late.token,abort.signal);assert.equal(report.status,'succeeded',report.error);assert(report.committed);assert(report.warnings.some(w=>w.includes('before cancellation')));assert.match((await read()).rawSql,/'ready'/);}finally{manager.lease=originalLease;}
   const casing=await read(),casePlan=reviewed(await service.preview(casing,renameText(casing.sql,'id','ID')));assert(!casePlan.steps.some(s=>/DROP COLUMN|DROP PRIMARY KEY/i.test(s)),'A case-only MySQL column change must retain its data and primary key');const changed=await service.apply(id,casePlan.token);assert.equal(changed.status,'succeeded',changed.error);assert.equal((await base.query(`SELECT ID FROM ${table} WHERE name='edited'`)).rows[0]?.c0,7);assert.equal((await base.details(qualified(child))).foreignKeys.length,1);
  }
 }finally{
  if(mysql){await base.query(`DROP TRIGGER IF EXISTS ${qualified(trigger)}`);}await base.query(`DROP TABLE IF EXISTS ${qualified(child)}`);await base.query(`DROP TABLE IF EXISTS ${table}${mysql?'':' CASCADE'}`);if(!mysql)await base.query(`DROP FUNCTION IF EXISTS ${qualified(prefix+'_fn')}()`);await base.query(`DROP TABLE IF EXISTS ${qualified(audit)}`);
 }
}
